package pyschema

import (
	"bytes"
	"errors"
	"fmt"
	"strings"
)

// Generator is the script that writes the table.
const Generator = "scripts/gen-pyschema.go"

// Path is where the Python client keeps the table, relative to the
// repository root.
const Path = "clients/python/src/guardana_control/enforce/_schema.py"

const pythonHead = "# Generated by " + Generator + " from the compiled descriptors of api/proto.\n" +
	"# Do not edit: `make docs-gen` rewrites this file, and a test fails when the two differ.\n" +
	"\n" +
	"# Each member of a message under its JSON name: (kind, shape, type name).\n"

// Python renders m as a Python module with no import: MESSAGES and ENUMS, in
// the model's order. It refuses a model with no message, and a name a
// double-quoted literal cannot carry as it is.
func Python(m Model) ([]byte, error) {
	if len(m.Messages) == 0 {
		return nil, errors.New("the model holds no message; refusing to write an empty table")
	}
	var buf bytes.Buffer
	buf.WriteString(pythonHead)
	buf.WriteString("MESSAGES: dict[str, dict[str, tuple[str, str, str]]] = {\n")
	for _, msg := range m.Messages {
		if err := pythonMessage(&buf, msg); err != nil {
			return nil, err
		}
	}
	buf.WriteString("}\nENUMS: dict[str, dict[str, int]] = {\n")
	for _, e := range m.Enums {
		if err := pythonEnum(&buf, e); err != nil {
			return nil, err
		}
	}
	buf.WriteString("}\n")
	return buf.Bytes(), nil
}

func pythonMessage(buf *bytes.Buffer, msg Message) error {
	if err := checkNames(msg.Name); err != nil {
		return err
	}
	if len(msg.Members) == 0 {
		fmt.Fprintf(buf, "    \"%s\": {},\n", msg.Name)
		return nil
	}
	fmt.Fprintf(buf, "    \"%s\": {\n", msg.Name)
	for _, member := range msg.Members {
		if err := checkNames(member.JSONName, string(member.Kind), string(member.Shape)); err != nil {
			return fmt.Errorf("%s: %w", msg.Name, err)
		}
		if member.TypeName != "" {
			if err := checkNames(member.TypeName); err != nil {
				return fmt.Errorf("%s: %w", msg.Name, err)
			}
		}
		fmt.Fprintf(buf, "        \"%s\": (\"%s\", \"%s\", \"%s\"),\n", member.JSONName, member.Kind, member.Shape, member.TypeName)
	}
	buf.WriteString("    },\n")
	return nil
}

func pythonEnum(buf *bytes.Buffer, e Enum) error {
	if err := checkNames(e.Name); err != nil {
		return err
	}
	pairs := make([]string, 0, len(e.Values))
	for _, v := range e.Values {
		if err := checkNames(v.Name); err != nil {
			return fmt.Errorf("%s: %w", e.Name, err)
		}
		pairs = append(pairs, fmt.Sprintf("\"%s\": %d", v.Name, v.Number))
	}
	fmt.Fprintf(buf, "    \"%s\": {%s},\n", e.Name, strings.Join(pairs, ", "))
	return nil
}

// checkNames refuses a name that is empty or holds anything but an ASCII
// letter, a digit, an underscore or a dot. A descriptor the compiler
// accepted spells its names with nothing else, apart from a JSON name its
// author chose.
func checkNames(names ...string) error {
	for _, name := range names {
		if name == "" {
			return errors.New("an empty name")
		}
		if i := strings.IndexFunc(name, func(r rune) bool { return !plain(r) }); i >= 0 {
			return fmt.Errorf("%q holds %U at byte %d, which the table does not write", name, []rune(name[i:])[0], i)
		}
	}
	return nil
}

func plain(r rune) bool {
	return r == '_' || r == '.' || (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}
